const ctx = new AudioContext();
const now = ctx.currentTime;

// Engine tone with Doppler-style pitch bend
const osc = ctx.createOscillator();
osc.type = 'sawtooth';
osc.frequency.setValueAtTime(90, now);
osc.frequency.linearRampToValueAtTime(130, now + 2.5);   // approaching
osc.frequency.linearRampToValueAtTime(70, now + 3.2);    // passing
osc.frequency.linearRampToValueAtTime(55, now + 6);      // receding

// Tire/wind noise
const buf = ctx.createBuffer(1, ctx.sampleRate * 6, ctx.sampleRate);
const d = buf.getChannelData(0);
for (let i = 0; i < d.length; i++) d[i] = Math.random() * 2 - 1;
const noise = ctx.createBufferSource();
noise.buffer = buf;
const filter = ctx.createBiquadFilter();
filter.type = 'bandpass';
filter.frequency.setValueAtTime(800, now);
filter.frequency.linearRampToValueAtTime(2500, now + 3);
filter.frequency.linearRampToValueAtTime(600, now + 6);

// Volume swell and fade
const gain = ctx.createGain();
gain.gain.setValueAtTime(0.001, now);
gain.gain.exponentialRampToValueAtTime(0.6, now + 3);
gain.gain.exponentialRampToValueAtTime(0.001, now + 6);

osc.connect(gain); noise.connect(filter).connect(gain); gain.connect(ctx.destination);
osc.start(now); noise.start(now); osc.stop(now + 6); noise.stop(now + 6);
```

